  const stp=['prev','perk','card','trim','spec','next'],si=stp.indexOf(a.step),pk=a.step!=='prev'&&run.plan?`<button class="btn sub peekb" data-cpeek="1">🗺️ Nächster Zoo ansehen</button>`:'',sg=[0,1,2,2,3,3][si],steps=`<div class="steps">${['Nächster Zoo','Verbessern','Karten & Deck','Team & Start'].map((l,i)=>`<span class="${i===sg?'on':i<sg?'ok':''}">${i<sg?'✓ ':''}${l}</span>`).join('')}</div>`;
