const zkCard=n=>[0,12,18][n]||0,zkRoll=a=>5+3*(a.rr||0); // Zoo-Kasse: Preise für weitere Karten und Neuwurf
function crewardStep(step){const run=activeSlot().run,a=run.reward;a.step=step;
  if(step==='card'){a.round=a.round||1;const H=run.habs||habsNow(),okHab=k=>{const h=CARDS[k].hab||CARDS[k].rq;return!h||H.includes(h)},pool=Object.keys(CARDS).filter(k=>okHab(k)&&!CARDS[k].gone&&!fsLocked(k)&&!(CARDS[k].cat==='verst'&&!verstOn(k))&&((CARDS[k].bonus_&&!run.cards.includes(k))||(!CARDS[k].bonus_&&['selten','sehr selten'].includes(CARDS[k].rar)&&!(CARDS[k].tags.includes('einmalig')&&run.deck.some(x=>baseK(x)===k)))));a.cards=shuffle(pool).slice(0,run.deckId==='forscher'&&run.zl?2:3);if(run.zl)a.cards=a.cards.map(k=>{if(CARDS[k].cat==='verst')return k;const r=Math.random(),e=r<.02?'r':r<.04?'s':r<.12?'g':'';return e?k+'~'+e:k})}
  if(step==='trim')a.trim=a.trim||0;
  if(step==='spec'){a.opts=rollSpecs(3);z2Rb(run,a.opts)}
  a.peek=false;if(step==='next')a.ev=run.plan?run.plan.ev:(c=>c.spring&&!run.zl?rollEvents({...c,s:0}):[])(campCfg(run.zoo));
  saveMeta();renderScreen()}
